module steward_support (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [1:0] IDLE          = 2'd0;\n    localparam [1:0] FIND_MIN_MAX  = 2'd1;\n    localparam [1:0] COUNT_SUPPORT = 2'd2;\n    localparam [1:0] FINISHED      = 2'd3;\n\n    reg [1:0] state;\n    reg [2:0] idx;\n    reg [7:0] min_val;\n    reg [7:0] max_val;\n    reg [3:0] count;\n    reg all_equal;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state   <= IDLE;\n            done    <= 1'b0;\n            result  <= 4'd0;\n            idx     <= 3'd0;\n            min_val <= 8'd0;\n            max_val <= 8'd0;\n            count   <= 4'd0;\n            all_equal <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        if (n < 3'd2) begin\n                            result <= 4'd0;\n                            done <= 1'b1;\n                            state <= FINISHED;\n                        end else begin\n                            idx <= 3'd1;  // Start with second element\n                            min_val <= arr_0;\n                            max_val <= arr_0;\n                            all_equal <= 1'b1;  // Assume equal until disproven\n                            state <= FIND_MIN_MAX;\n                        end\n                    end\n                end\n\n                FIND_MIN_MAX: begin\n                    if (idx < n) begin\n                        case (idx)\n                            3'd1: begin\n                                if (arr_1 < min_val) min_val <= arr_1;\n                                if (arr_1 > max_val) max_val <= arr_1;\n                                if (arr_1 != min_val) all_equal <= 1'b0;\n                            end\n                            3'd2: begin\n                                if (arr_2 < min_val) min_val <= arr_2;\n                                if (arr_2 > max_val) max_val <= arr_2;\n                                if (arr_2 != min_val) all_equal <= 1'b0;\n                            end\n                            3'd3: begin\n                                if (arr_3 < min_val) min_val <= arr_3;\n                                if (arr_3 > max_val) max_val <= arr_3;\n                                if (arr_3 != min_val) all_equal <= 1'b0;\n                            end\n                            3'd4: begin\n                                if (arr_4 < min_val) min_val <= arr_4;\n                                if (arr_4 > max_val) max_val <= arr_4;\n                                if (arr_4 != min_val) all_equal <= 1'b0;\n                            end\n                            3'd5: begin\n                                if (arr_5 < min_val) min_val <= arr_5;\n                                if (arr_5 > max_val) max_val <= arr_5;\n                                if (arr_5 != min_val) all_equal <= 1'b0;\n                            end\n                            3'd6: begin\n                                if (arr_6 < min_val) min_val <= arr_6;\n                                if (arr_6 > max_val) max_val <= arr_6;\n                                if (arr_6 != min_val) all_equal <= 1'b0;\n                            end\n                            3'd7: begin\n                                if (arr_7 < min_val) min_val <= arr_7;\n                                if (arr_7 > max_val) max_val <= arr_7;\n                                if (arr_7 != min_val) all_equal <= 1'b0;\n                            end\n                        endcase\n                        idx <= idx + 3'd1;\n                    end else begin\n                        if (all_equal || (min_val == max_val)) begin\n                            result <= 4'd0;\n                            done <= 1'b1;\n                            state <= FINISHED;\n                        end else begin\n                            idx <= 3'd0;\n                            count <= 4'd0;\n                            state <= COUNT_SUPPORT;\n                        end\n                    end\n                end\n\n                COUNT_SUPPORT: begin\n                    if (idx < n) begin\n                        case (idx)\n                            3'd0: if ((arr_0 > min_val) && (arr_0 < max_val)) count <= count + 4'd1;\n                            3'd1: if ((arr_1 > min_val) && (arr_1 < max_val)) count <= count + 4'd1;\n                            3'd2: if ((arr_2 > min_val) && (arr_2 < max_val)) count <= count + 4'd1;\n                            3'd3: if ((arr_3 > min_val) && (arr_3 < max_val)) count <= count + 4'd1;\n                            3'd4: if ((arr_4 > min_val) && (arr_4 < max_val)) count <= count + 4'd1;\n                            3'd5: if ((arr_5 > min_val) && (arr_5 < max_val)) count <= count + 4'd1;\n                            3'd6: if ((arr_6 > min_val) && (arr_6 < max_val)) count <= count + 4'd1;\n                            3'd7: if ((arr_7 > min_val) && (arr_7 < max_val)) count <= count + 4'd1;\n                        endcase\n                        idx <= idx + 3'd1;\n                    end else begin\n                        result <= count;\n                        done <= 1'b1;\n                        state <= FINISHED;\n                    end\n                end\n\n                FINISHED: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule